'use client';

import { useEffect } from 'react';
import { pronounce, stopPronouncing } from '../../lib/speech';
import type { LearningItem } from '../../lib/types';
import { SpeakButton } from '../speech/speak-button';
import { PronunciationFrame } from './pronunciation-practice';

interface ListeningItemProps {
  item: LearningItem;
  /** Its audio generated by Kokoro (MEM-39); without it, the browser's voice. */
  audioUrl?: string;
  /** The pronunciation assessment is configured on the server (MEM-90). */
  canAssess: boolean;
}

/**
 * MEM-101: an item at the step « Écoute et prononciation » of the learning.
 * Nothing written: the item is only heard (MEM-100, adjustment), its
 * English read as soon as the page shows it (Kokoro, else the browser's
 * voice); « Réécouter » reads it again, and « Évaluer ma prononciation » is
 * the frame of the review (same components, MEM-90 to MEM-92): optional,
 * it never holds back the next item. Nothing here changes the state of the
 * item. Keyed by the item by its parent: the next one starts afresh, and
 * the recording of the previous one is forgotten.
 */
export function ListeningItem({ item, audioUrl, canAssess }: ListeningItemProps) {
  // Read as it appears. Browsers may refuse a sound the user did not start
  // (no click yet on the page): then nothing is said, and « Réécouter » is there.
  useEffect(() => {
    pronounce(item.word, audioUrl);
    return stopPronouncing;
  }, [item.word, audioUrl]);

  return (
    <article className="review-card">
      <div className="review-card__body review-card__body--with-practice listening__body">
        <div className="review-card__body-main">
          <p className="listening__actions">
            <SpeakButton text={item.word} audioUrl={audioUrl} label="Réécouter" />
          </p>
        </div>
        <PronunciationFrame itemId={item.id} available={canAssess} />
      </div>
    </article>
  );
}
